/**
 * A protocol-only publication-order test. It starts a real import, but invokes the defensive terminal branch with a
 * null failure to pause its fallback exception construction. This is not a concurrent cleanup-I/O reproduction.
 * Reflection only reads the real import/monitor and invokes that branch; it never writes private state.
 */
@Isolated
class LmdbInitialRunImportAdmissionFailureTest {

	private static final String FALLBACK = "The initial run import ended without completing";

	@TempDir(cleanup = CleanupMode.ON_SUCCESS)
	Path directory;

	@Test
	@Timeout(60)
	void defensiveTerminalFailureMustPublishBeforeImportAdmissionOpens() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setForceSync(true)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setBulkOperationSize(64);
		LmdbStore sail = new LmdbStore(directory.toFile(), config);
		sail.init();
		ExecutorService workers = Executors.newFixedThreadPool(2);
		CountDownLatch constructingFailure = new CountDownLatch(1);
		CountDownLatch releaseFailure = new CountDownLatch(1);
		CountDownLatch peerStarted = new CountDownLatch(1);
		AtomicReference<IllegalStateException> fallback = new AtomicReference<>();
		AtomicReference<Thread> ownerThread = new AtomicReference<>();
		AtomicReference<Thread> peerThread = new AtomicReference<>();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			Object monitor = readField(backing, "initialRunImportMonitor");
			Method terminal = LmdbSailStore.class.getDeclaredMethod("endInitialRunImport",
					LmdbInitialRunImport.class, boolean.class, Throwable.class);
			terminal.setAccessible(true);
			Future<?> owner = workers.submit(() -> {
				ownerThread.set(Thread.currentThread());
				try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					var values = SimpleValueFactory.getInstance();
					for (int row = 0; row < 130; row++) {
						writer.addStatement(values.createIRI("urn:admission-failure:subject:" + row),
								values.createIRI("urn:admission-failure:predicate"),
								values.createLiteral("value " + row));
					}
					assertTrue(backing.isInitialRunImportActive(), "the protocol starts with an actual NONE import");
					assertThat(directory.resolve(LmdbInitialRunImport.MARKER_FILE_NAME)).exists();
					LmdbInitialRunImport runImport = (LmdbInitialRunImport) readField(backing, "initialRunImport");
					assertSame(writer, runImport.owner);
					try (MockedConstruction<IllegalStateException> ignored = mockConstruction(
							IllegalStateException.class,
							(exception, context) -> {
								assertThat(context.arguments()).isEqualTo(List.of(FALLBACK));
								assertSame(ownerThread.get(), Thread.currentThread());
								assertTrue(Thread.holdsLock(monitor));
								assertTrue(fallback.compareAndSet(null, exception),
										"construct the terminal failure once");
								constructingFailure.countDown();
								assertTrue(releaseFailure.await(30, TimeUnit.SECONDS),
										"release the owned terminal boundary");
							})) {
						try {
							// No normal caller is claimed to pass null here. This defensive branch provides an exact
							// pause before failure assignment, after/before owner clearance according to its ordering.
							terminal.invoke(backing, runImport, false, null);
						} catch (InvocationTargetException invocation) {
							throw new AssertionError(
									"The defensive terminal branch must record, not throw, its failure",
									invocation.getCause());
						}
					}
				}
				return null;
			});
			boolean reached = constructingFailure.await(20, TimeUnit.SECONDS);
			if (!reached && owner.isDone()) {
				owner.get(); // Surface unsupported construction mocking or fixture failures, not just a latch timeout.
			}
			assertTrue(reached, "the real terminal branch must reach the fallback construction boundary");
			Future<Throwable> peer = workers.submit(() -> {
				peerThread.set(Thread.currentThread());
				peerStarted.countDown();
				try {
					backing.awaitInitialRunImport(new Object());
					return null;
				} catch (Throwable failure) {
					return failure;
				}
			});
			assertTrue(peerStarted.await(10, TimeUnit.SECONDS), "the independent peer must actually start");
			boolean completedBeforePublication;
			try {
				completedBeforePublication = awaitPeerReturnOrOwnedMonitor(peer, peerThread.get(), ownerThread.get(),
						monitor);
			} finally {
				releaseFailure.countDown();
			}
			owner.get(20, TimeUnit.SECONDS);
			Throwable peerFailure = peer.get(20, TimeUnit.SECONDS);
			System.out.println("TERMINAL_ADMISSION_PROTOCOL premature=" + completedBeforePublication
					+ ", peerFailure=" + (peerFailure == null ? "none" : peerFailure.getClass().getSimpleName()));
			assertAll(
					() -> assertFalse(completedBeforePublication,
							"a peer cannot pass admission while the terminal failure is still being published"),
					() -> assertThat(peerFailure).isInstanceOf(SailException.class),
					() -> assertTrue(hasCause(peerFailure, fallback.get()),
							"retain the exact terminal failure identity"),
					() -> assertThat(backing.initialRunImportsCompleted()).isZero(),
					() -> assertFalse(backing.isInitialRunImportActive()));
		} finally {
			releaseFailure.countDown();
			// Never close native environments under an unreaped owner. Timeout is a failure, not evidence of blocking.
			boolean interrupted = Thread.interrupted();
			try {
				workers.shutdownNow();
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
				boolean terminated = workers.isTerminated();
				while (!terminated && System.nanoTime() < deadline) {
					try {
						terminated = workers.awaitTermination(Math.max(1L, deadline - System.nanoTime()),
								TimeUnit.NANOSECONDS);
					} catch (InterruptedException interruption) {
						interrupted = true;
					}
				}
				assertTrue(terminated, "reap both owned protocol workers");
				sail.shutDown();
			} finally {
				if (interrupted) {
					Thread.currentThread().interrupt();
				}
			}
		}
	}

	/** Returns true only for a completed peer, false only for proven blocking on the exact owner-held monitor. */
	private static boolean awaitPeerReturnOrOwnedMonitor(Future<?> peer, Thread peerThread, Thread ownerThread,
			Object monitor) {
		ThreadMXBean threads = ManagementFactory.getThreadMXBean();
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (System.nanoTime() < deadline) {
			if (peer.isDone()) {
				return true;
			}
			ThreadInfo info = threads.getThreadInfo(peerThread.threadId(), 24);
			if (info != null) {
				LockInfo lock = info.getLockInfo();
				boolean exactMonitor = lock != null && lock.getIdentityHashCode() == System.identityHashCode(monitor)
						&& lock.getClassName().equals(monitor.getClass().getName());
				boolean actualAdmission = Arrays.stream(info.getStackTrace())
						.anyMatch(frame -> frame.getClassName().equals(LmdbSailStore.class.getName())
								&& frame.getMethodName().equals("awaitInitialRunImport"));
				boolean ownerBlocks = info.getThreadState() == Thread.State.BLOCKED
						&& info.getLockOwnerId() == ownerThread.threadId();
				boolean monitorWait = info.getThreadState() == Thread.State.WAITING;
				if (exactMonitor && actualAdmission && (ownerBlocks || monitorWait)) {
					return false;
				}
			}
			Thread.yield();
		}
		throw new AssertionError("Peer neither completed nor demonstrably blocked on the initial-import monitor");
	}

	private static Object readField(LmdbSailStore backing, String name) throws ReflectiveOperationException {
		Field field = LmdbSailStore.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(backing);
	}

	private static boolean hasCause(Throwable failure, Throwable expected) {
		Set<Throwable> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Throwable current = failure; current != null && seen.add(current); current = current.getCause()) {
			if (current == expected) {
				return true;
			}
		}
		return false;
	}
}
